#include "facts/generated/facts_data.hpp"

namespace nikos::facts::data {

const Fact kHumanFacts[kFactsPerCategory] = {
    {u8"human-001", u8"Języki migowe świata", u8"Języki migowe nie są takie same na całym świecie. Brytyjski i amerykański język migowy znacznie się różnią."},
    {u8"human-002", u8"Rozmowa gwizdem", u8"Na wyspie La Gomera można przekazać całe zdania gwizdem. Silbo Gomero zastępuje dźwięki hiszpańskich słów gwizdami."},
    {u8"human-003", u8"Ponad 800 języków", u8"W Papui-Nowej Gwinei używa się ponad 800 języków. To jeden z najbardziej różnorodnych językowo krajów świata."},
    {u8"human-004", u8"Trzy pisma w jednym zdaniu", u8"W Japonii w jednym zdaniu spotykają się trzy rodzaje pisma. To kanji, hiragana i katakana, używane do różnych celów."},
    {u8"human-005", u8"Północ zamiast lewa", u8"W australijskim Guugu Yimithirr mówi się „północ” zamiast „lewo”. Nawet położenie drobnych rzeczy opisuje się stronami świata."},
    {u8"human-006", u8"Hieroglify w obie strony", u8"Egipskie hieroglify można było czytać w obu kierunkach. Stronę czytania wskazywały twarze ludzi i zwierząt w znakach."},
    {u8"human-007", u8"Złote pęknięcia", u8"W Japonii pęknięć naprawionej ceramiki nie zawsze się ukrywa. W kintsugi podkreśla się je lakierem z drobinami złota."},
    {u8"human-008", u8"Radosny Dzień Zmarłych", u8"W Meksyku Día de Muertos łączy pamięć o zmarłych z barwnymi ołtarzami, kwiatami i muzyką. Rodziny przygotowują dary dla upamiętnienia bliskich."},
    {u8"human-009", u8"Kraj saun", u8"W Finlandii jest ponad trzy miliony saun. Sauna bywa miejscem odpoczynku i spotkań z innymi ludźmi."},
    {u8"human-010", u8"Wieża z ludzi", u8"W Katalonii powstają wielopiętrowe wieże z ludzi. Uczestnicy tradycji castells stoją sobie na ramionach."},
    {u8"human-011", u8"Wyspy z trzciny", u8"Na jeziorze Titicaca ludzie mieszkają na pływających wyspach. Lud Uros buduje je z trzciny totora, stale dokładając nowe warstwy."},
    {u8"human-012", u8"Malowanie ziemi", u8"W Indiach układa się na ziemi kolorowe wzory zwane rangoli. Powstają z proszków, piasku lub płatków kwiatów."},
    {u8"human-013", u8"Dwa tony naraz", u8"W mongolskim śpiewie gardłowym słychać dwa tony naraz. Niski dźwięk łączy się z wysoką melodią tworzoną jednym głosem."},
    {u8"human-014", u8"Obraz z kropek", u8"Puentylizm pozwala namalować obraz z maleńkich kropek. Oglądane z daleka kolory łączą się w oczach widza."},
    {u8"human-015", u8"Mandala z piasku", u8"Mnisi tybetańscy tworzą bardzo dokładne wzory z piasku. Gotowe mandale bywają zamiatane na znak przemijania."},
    {u8"human-016", u8"Teatr z cieni", u8"W Indonezji w tradycyjnym teatrze występują cienie lalek. Skórzane figurki porusza się przed podświetlonym ekranem."},
    {u8"human-017", u8"Kolorowe litery", u8"Dla niektórych ludzi litery i cyfry mają własne kolory. To synestezja, czyli łączenie różnych wrażeń zmysłowych."},
    {u8"human-018", u8"Wyobraźnia bez obrazów", u8"Nie każdy potrafi wyobrazić sobie obraz w głowie. To afantazja — myślenie bez tworzenia obrazów w umyśle."},
    {u8"human-019", u8"Twarz w drzewie", u8"Czasem w sękach drzewa dostrzegamy ludzką twarz. To pareidolia: mózg widzi znajomy wzór tam, gdzie go nie ma."},
    {u8"human-020", u8"Niewidoczna zmiana", u8"Można nie zauważyć dużej zmiany w oglądanym obrazie. Gdy uwaga jest zajęta, różnica łatwo nam umyka."},
    {u8"human-021", u8"Pamięć podczas snu", u8"Sen pomaga utrwalić to, czego nauczyliśmy się w dzień. Podczas odpoczynku mózg przetwarza nowe wspomnienia."},
    {u8"human-022", u8"Ludzka echolokacja", u8"Niektórzy ludzie potrafią rozpoznawać przeszkody po echu. Nasłuchują odbicia kliknięć wydawanych językiem."},
    {u8"human-023", u8"Samodzielne łaskotanie", u8"Samodzielne łaskotanie zwykle jest mniej odczuwalne. Mózg przewiduje własny dotyk i osłabia jego wrażenie."},
    {u8"human-024", u8"Mózg bez receptorów bólu", u8"Sama tkanka mózgowa nie ma receptorów bólu. Boleć mogą jednak otaczające ją opony mózgowe oraz niektóre naczynia krwionośne."},
    {u8"human-025", u8"Niewidzialna plamka", u8"W każdym oku jest mała ślepa plamka bez komórek światłoczułych. Mózg zwykle uzupełnia brak obrazu, więc jej nie zauważamy."},
    {u8"human-026", u8"Pismo kobiet nüshu", u8"W Chinach kobiety używały osobnego pisma o nazwie nüshu. Zapisywały nim listy, pieśni i historie swojego życia."},
    {u8"human-027", u8"Spółgłoski jak kliknięcia", u8"W języku xhosa niektóre spółgłoski brzmią jak mlaskanie językiem. Takie kliknięcia są częścią słów, a nie tylko odgłosami."},
    {u8"human-028", u8"Tajemnica języka baskijskiego", u8"Język baskijski nie ma potwierdzonych żyjących krewnych. Choć mówi się nim w Europie, nie należy do rodziny indoeuropejskiej."},
    {u8"human-029", u8"Bęben, który mówi", u8"W Afryce Zachodniej bębny potrafią naśladować ludzką mowę. Zmiana napięcia skóry zmienia wysokość dźwięku."},
    {u8"human-030", u8"Historie rysowane w piasku", u8"Na Vanuatu rysunki na piasku potrafią opowiadać historie. Wzory tworzy się jednym palcem, często bez odrywania go od ziemi."},
    {u8"human-031", u8"Trzynaście miesięcy", u8"W Etiopii rok ma trzynaście miesięcy. Dwanaście ma po 30 dni, a ostatni tylko pięć lub sześć."},
    {u8"human-032", u8"Wspólne robienie kimchi", u8"W Korei wiele rodzin przygotowuje jesienią zapasy kimchi. Zwyczaj kimjang łączy wspólną pracę z dzieleniem się jedzeniem."},
    {u8"human-033", u8"Nazwisko od imienia rodzica", u8"W Islandii nazwisko często powstaje od imienia matki lub ojca. Końcówka -son oznacza syna, a -dóttir córkę."},
    {u8"human-034", u8"Powitanie nosami", u8"Maorysi w Nowej Zelandii mogą witać gości, dotykając się nosami. To hongi, tradycyjny gest powitania i pokoju."},
    {u8"human-035", u8"Nowy Rok pełen wody", u8"W Tajlandii podczas Nowego Roku ludzie oblewają się wodą. Songkran symbolizuje oczyszczenie i życzenie pomyślności."},
    {u8"human-036", u8"Rysowanie gorącym woskiem", u8"W Indonezji wzory na tkaninach maluje się gorącym woskiem. W batiku wosk osłania wybrane miejsca przed farbą."},
    {u8"human-037", u8"Obraz malowany na wodzie", u8"W Turcji powstają obrazy malowane na powierzchni wody. W technice ebru barwniki przenosi się z wody na papier."},
    {u8"human-038", u8"Znaki ukryte w przysłowiach", u8"W Ghanie znaki adinkra zdobią ubrania i tkaniny. Wiele z tych symboli nawiązuje do przysłów i wartości."},
    {u8"human-039", u8"Polskie papierowe wycinanki", u8"W Łowiczu ozdoby wycina się nawet z wielu warstw papieru. Na Kurpiach powstają też symetryczne wzory z jednej kartki."},
    {u8"human-040", u8"Buty jako instrument", u8"We flamenco tancerz może wybijać rytm uderzeniami butów. Stopy stają się wtedy instrumentem obok gitary i dłoni."},
    {u8"human-041", u8"Usta oszukują słuch", u8"To, co widzimy na ustach, może zmienić usłyszany dźwięk. W efekcie McGurka ten sam głos brzmi inaczej przy innym obrazie."},
    {u8"human-042", u8"Gumowa ręka jak własna", u8"Można poczuć, że gumowa ręka jest naszą własną. Dzieje się tak przy równoczesnym dotykaniu jej i ukrytej ręki."},
    {u8"human-043", u8"Pałac pamięci", u8"Mistrzowie pamięci spacerują w wyobraźni po znanych miejscach. Rozmieszczają tam informacje, które chcą zapamiętać."},
    {u8"human-044", u8"Wspomnienie, którego nie było", u8"Człowiek może pamiętać coś, co nigdy się nie wydarzyło. Sugestywne pytania potrafią zniekształcić wspomnienia."},
    {u8"human-045", u8"Superrozpoznawacze twarzy", u8"Niektórzy ludzie rozpoznają twarze dużo lepiej niż inni. Superrozpoznawacze pomagają nawet analizować nagrania z kamer."},
    {u8"human-046", u8"Nurkujące kobiety z Jeju", u8"Na koreańskiej wyspie Jeju kobiety nurkują bez butli tlenowych. Haenyeo zbierają pod wodą małże i jeżowce."},
    {u8"human-047", u8"Dlaczego palce się marszczą?", u8"Palce marszczą się w wodzie nie tylko przez jej wchłanianie. Nerwy zwężają tam naczynia krwionośne i skóra się fałduje."},
    {u8"human-048", u8"Oko oddycha powietrzem", u8"Przezroczysta rogówka oka nie ma własnych naczyń krwionośnych. Tlen pobiera między innymi z powietrza przez warstwę łez."},
    {u8"human-049", u8"Brawa bez dyrygenta", u8"Brawa na widowni potrafią same zsynchronizować swój rytm. Ludzie zaczynają klaskać razem, choć nikt nimi nie dyryguje."},
    {u8"human-050", u8"Człowiek naprawdę świeci", u8"Ludzkie ciało naprawdę emituje bardzo słabe światło. Jest około tysiąc razy zbyt słabe, by zobaczyć je gołym okiem."},
    {u8"human-051", u8"Wspólny przodek", u8"Ludzie i współczesne szympansy mają wspólnego przodka. Ludzie nie wywodzą się od dzisiejszych szympansów."},
    {u8"human-052", u8"Wiele gatunków ludzi", u8"Homo sapiens nie był jedynym gatunkiem człowieka. W przeszłości żyli też neandertalczycy i denisowianie."},
    {u8"human-053", u8"Neandertalskie DNA", u8"Wiele osób poza Afryką ma niewielki udział DNA neandertalskiego. To ślad dawnych kontaktów między populacjami."},
    {u8"human-054", u8"Dwunożność przed wielkim mózgiem", u8"Dwunożność rozwinęła się u przodków ludzi przed znacznym wzrostem mózgu. Ewolucja nie przebiegała jednym krokiem."},
    {u8"human-055", u8"Lucy z Etiopii", u8"Szkielet Lucy ma ponad trzy miliony lat. Należy do gatunku Australopithecus afarensis."},
    {u8"human-056", u8"Narzędzia starsze od sapiens", u8"Kamienne narzędzia powstawały długo przed pojawieniem się Homo sapiens. Część ma ponad dwa miliony lat."},
    {u8"human-057", u8"Kolor skóry i Słońce", u8"Zróżnicowanie pigmentacji skóry wiąże się między innymi z promieniowaniem UV. To wynik długiej adaptacji populacji."},
    {u8"human-058", u8"Trawienie mleka", u8"U części dorosłych ludzi enzym laktaza pozostaje aktywny. Ta cecha upowszechniła się w niektórych populacjach pasterskich."},
    {u8"human-059", u8"Zmienne zęby mądrości", u8"Nie u każdego wyrastają wszystkie zęby mądrości. Ich liczba i rozwój są zróżnicowane."},
    {u8"human-060", u8"Przystosowanie do wysokości", u8"Populacje Tybetu i Andów wykształciły odmienne adaptacje do rozrzedzonego powietrza. Nie istnieje jedna droga przystosowania."},
    {u8"human-061", u8"Religie mają różne korzenie", u8"Nie wszystkie religie mają jednego założyciela ani jedną datę powstania. Wiele tradycji rozwijało się stopniowo."},
    {u8"human-062", u8"Religie monoteistyczne", u8"Judaizm, chrześcijaństwo i islam są religiami monoteistycznymi. Różnią się jednak tekstami i praktykami."},
    {u8"human-063", u8"Tradycje hinduistyczne", u8"Hinduizm obejmuje wiele szkół, bóstw i praktyk. Nie ma jednego założyciela wspólnego dla wszystkich nurtów."},
    {u8"human-064", u8"Buddyzm i cierpienie", u8"W centrum nauk buddyjskich stoją cierpienie i droga do jego ustania. Tradycje buddyjskie różnią się między sobą."},
    {u8"human-065", u8"Sikhizm w Pendżabie", u8"Sikhizm ukształtował się w Pendżabie pod koniec XV wieku. Jego pierwszym guru był Nanak."},
    {u8"human-066", u8"Szinto i kami", u8"W japońskiej tradycji szinto ważne są kami, związane z naturą i miejscami. Szinto nie ma jednego założyciela."},
    {u8"human-067", u8"Święta ziemia przodków", u8"W wielu rdzennych tradycjach konkretne miejsca mają znaczenie duchowe. Wierzenia i praktyki różnią się jednak między społecznościami."},
    {u8"human-068", u8"Kalendarze religijne", u8"Różne tradycje wyznaczają święta według innych kalendarzy. Stosuje się między innymi kalendarze księżycowe i słoneczne."},
    {u8"human-069", u8"Post w wielu tradycjach", u8"Post jest obecny w wielu religiach, ale ma różne zasady i znaczenia. Nie zawsze polega na całkowitym niejedzeniu."},
    {u8"human-070", u8"Pielgrzymowanie", u8"Pielgrzymki występują w wielu tradycjach religijnych. Mogą prowadzić do sanktuariów, rzek lub innych ważnych miejsc."},
    {u8"human-071", u8"Opowieści o stworzeniu", u8"Kultury świata mają różne opowieści o początkach świata. Takie mity nie są tym samym co modele naukowe."},
    {u8"human-072", u8"Rytuały przejścia", u8"W wielu kulturach obrzędy zaznaczają wejście w nowy etap życia. Mogą dotyczyć dorosłości, małżeństwa lub śmierci."},
    {u8"human-073", u8"Człowiek i ogień", u8"Kontrolowane używanie ognia było ważne dla dawnych ludzi. Dokładna data jego pierwszego opanowania pozostaje sporna."},
    {u8"human-074", u8"Skąd bierze się czkawka?", u8"Czkawka to odruch związany z nagłym skurczem przepony. Charakterystyczny dźwięk powstaje przy zamknięciu głośni."},
    {u8"human-075", u8"Nie każdy czuje gorzki smak", u8"Wrażliwość na niektóre gorzkie związki zależy częściowo od genów. Dlatego ten sam smak ludzie mogą odbierać inaczej."},
    {u8"human-076", u8"Po co nam gęsia skórka", u8"Gęsia skórka powstaje przez skurcz małych mięśni przy włosach. To pozostałość reakcji, która u futrzastych ssaków nastrosza sierść."},
    {u8"human-077", u8"Dlaczego ziewamy", u8"Ziewanie występuje u ludzi i wielu innych kręgowców. Jego dokładna funkcja nadal jest przedmiotem badań."},
    {u8"human-078", u8"Smak ma więcej wymiarów", u8"Język wykrywa między innymi smak słodki, słony i umami. Aromat potraw silnie zależy też od węchu."},
    {u8"human-079", u8"Czemu nie widzimy nosa", u8"Nos stale znajduje się w polu widzenia naszych oczu. Mózg zwykle ignoruje tę przewidywalną informację."},
    {u8"human-080", u8"Mózg zużywa energię", u8"Mózg dorosłego zużywa znaczną część energii spoczynkowej organizmu. Jest aktywny także podczas snu."},
    {u8"human-081", u8"Sen i zegar biologiczny", u8"Światło pomaga synchronizować dobowy rytm człowieka. Istotną rolę odgrywa niewielki obszar podwzgórza."},
    {u8"human-082", u8"Dlaczego mamy odciski", u8"Linie papilarne powstają przed urodzeniem i różnią się między palcami. Mogą wspomagać kontakt skóry z powierzchnią."},
    {u8"human-083", u8"Lewa i prawa półkula", u8"Półkule mózgu mają pewne wyspecjalizowane funkcje. Popularny podział na ludzi „lewo-” i „prawopółkulowych” jest uproszczeniem."},
    {u8"human-084", u8"Mózg przewiduje ruch", u8"Podczas chwytania kubka mózg szacuje potrzebną siłę. Aktualizuje ten szacunek na podstawie dotyku i doświadczenia."},
    {u8"human-085", u8"Skąd bierze się rumieniec", u8"Rumieniec to zmiana przepływu krwi w skórze twarzy. Może pojawiać się w reakcji na silne emocje."},
    {u8"human-086", u8"Czy człowiek jest rybą?", u8"Ludzie wywodzą się z dawnej linii ryb mięśniopłetwych. W klasyfikacji kladystycznej należymy do tej gałęzi ewolucyjnego drzewa życia."},
    {u8"human-087", u8"Nasza wspólna matka?", u8"„Mitochondrialna Ewa” oznacza wspólną przodkinię pewnej linii DNA. Nie była jedyną kobietą żyjącą w swoich czasach."},
    {u8"human-088", u8"Przodkowie z Afryki", u8"Najstarsze znane szczątki Homo sapiens pochodzą z Afryki. Rozwój naszego gatunku nie był pojedynczym prostym marszem."},
    {u8"human-089", u8"Dlaczego ludzie się różnią", u8"Większość ludzkiej zmienności genetycznej występuje wewnątrz populacji. Granice państw nie wyznaczają ostrych granic biologicznych."},
    {u8"human-090", u8"Dziecko uczy się języka", u8"Niemowlęta rozpoznają dźwiękowe wzorce mowy jeszcze przed wypowiadaniem słów. Kontakt z językiem kształtuje tę zdolność."},
    {u8"human-091", u8"Wspólna muzyka ludzi", u8"Muzyka występuje we wszystkich dobrze zbadanych społeczeństwach. Jej style i znaczenia bywają jednak bardzo różne."},
    {u8"human-092", u8"Wiele sposobów liczenia", u8"Systemy liczenia nie zawsze używały podstawy dziesiętnej. Babilończycy stosowali system sześćdziesiątkowy."},
    {u8"human-093", u8"Niewidoczne mikroby", u8"Na ludzkiej skórze i w jelitach żyją liczne mikroorganizmy. Ich społeczności tworzą mikrobiom."},
    {u8"human-094", u8"O co chodzi z placebo", u8"Oczekiwania i kontekst terapii mogą zmieniać odczuwanie objawów. Nie oznacza to, że placebo leczy każdą chorobę."},
    {u8"human-095", u8"Fantomowa kończyna", u8"Niektórzy ludzie nadal czują rękę lub nogę po jej amputacji. Mózg może zachowywać reprezentację utraconej kończyny przez wiele lat."},
    {u8"human-096", u8"Dlaczego śmiejemy się razem", u8"Śmiech często pojawia się podczas kontaktów społecznych. Może pomagać sygnalizować więź i intencje."},
    {u8"human-097", u8"Gesty pomagają mówić", u8"Ludzie spontanicznie gestykulują podczas rozmowy. Gesty mogą też wspierać myślenie i zapamiętywanie."},
    {u8"human-098", u8"Co to jest deja vu", u8"Déjà vu to wrażenie, że nowa sytuacja została już przeżyta. Badacze wiążą je z mechanizmami pamięci i znajomości."},
    {u8"human-099", u8"Ruch, którego nie ma", u8"Dwa nieruchome obrazy pokazane w odpowiedniej kolejności mogą dać wrażenie ruchu. To jedno ze zjawisk ruchu pozornego wykorzystywanych w animacji."},
    {u8"human-100", u8"Ciało ma własny kompas", u8"Propriocepcja pomaga wiedzieć, gdzie znajdują się nasze kończyny. Działa nawet wtedy, gdy nie patrzymy na ręce."},
};

}  // namespace nikos::facts::data
